function stworzPrzelacznikTrybu(tryby) {
  let indeks = 0;
  return () => {
    const aktualny = tryby[indeks];
    indeks = (indeks + 1) % tryby.length;
    return aktualny;
  };
}

const nastepnyTryb = stworzPrzelacznikTrybu(["dzien", "noc", "auto"]);
console.log(nastepnyTryb()); // "dzien"
console.log(nastepnyTryb()); // "noc"
console.log(nastepnyTryb()); // "auto"
console.log(nastepnyTryb()); // "dzien" - wraca na poczatek

function stworzKontrolerLogowania(maksProb) {
  let liczbaProb = 0;
  return () => {
    liczbaProb = liczbaProb + 1;
    if (liczbaProb > maksProb) {
      return "zablokowano";
    }
    return "proba " + liczbaProb;
  };
}

const kontroler = stworzKontrolerLogowania(2);
