console.log(kontroler()); // "proba 2"
console.log(kontroler()); // "zablokowano"

function stworzHistorieOperacji() {
  const historia = [];
  return {
    wykonaj: (opis) => { historia.push(opis); },
    ostatnia: () => historia[historia.length - 1],
    liczba: () => historia.length
  };
}

const historia = stworzHistorieOperacji();
historia.wykonaj("dodano produkt");
historia.wykonaj("usunieto produkt");

console.log(historia.ostatnia()); // "usunieto produkt"
console.log(historia.liczba());   // 2

