console.log(generujId()); // 1001

function stworzSredniaRuchoma() {
  let suma = 0;
  let liczbaElementow = 0;
  return (nowaLiczba) => {
    suma += nowaLiczba;
    liczbaElementow += 1;
    return suma / liczbaElementow;
  };
}

const srednia = stworzSredniaRuchoma();
console.log(srednia(10)); // 10
console.log(srednia(20)); // 15
console.log(srednia(30)); // 20

function stworzLicznikDopasowan(predykat) {
  let liczba = 0;
  return (wartosc) => {
    if (predykat(wartosc)) {
      liczba += 1;
    }
    return liczba;
  };
}

const liczParzyste = stworzLicznikDopasowan(n => n % 2 === 0);
console.log(liczParzyste(4)); // 1
console.log(liczParzyste(5)); // 1 (nie zmienia sie)
console.log(liczParzyste(6)); // 2

function stworzSejfZResetem() {
  let kod = "0000";
  return {
    ustawKod: (nowyKod) => { kod = nowyKod; },
    sprawdz: (proba) => proba === kod
  };
}

const sejf = stworzSejfZResetem();
console.log(sejf.sprawdz("0000")); // true
sejf.ustawKod("9999");
console.log(sejf.sprawdz("0000")); // false
console.log(sejf.sprawdz("9999")); // true

function stworzRejestrGlosow() {
  const glosy = { tak: 0, nie: 0 };
  return {
    zaglosuj: (opcja) => { glosy[opcja] = glosy[opcja] + 1; },
    wynik: () => glosy
  };
}

const glosowanie = stworzRejestrGlosow();
glosowanie.zaglosuj("tak");
glosowanie.zaglosuj("tak");
glosowanie.zaglosuj("nie");
console.log(glosowanie.wynik()); // { tak: 2, nie: 1 }

